using Microsoft.EntityFrameworkCore;
using QualifyAI.Domain;
using QualifyAI.Infrastructure.Acquisition;
using QualifyAI.Persistence.SqlServer;
namespace QualifyAI.Api;
public static class AutonomousAcquisitionEndpoints{public static IEndpointRouteBuilder MapAutonomousAcquisition(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/autonomous-acquisition");g.MapGet("/templates",(IAutonomousAcquisitionTemplateRegistry r)=>Results.Ok(r.List()));g.MapGet("/tenants/{tenantId}/agents",async(Guid tenantId,AppDbContext db,CancellationToken ct)=>Results.Ok(await db.AutonomousAcquisitionAgents.Where(x=>x.TenantId==tenantId).OrderByDescending(x=>x.UpdatedAtUtc).ToListAsync(ct)));g.MapPost("/tenants/{tenantId}/agents",async(Guid tenantId,AutonomousAcquisitionAgent input,AppDbContext db,IAutonomousAcquisitionTemplateRegistry templates,CancellationToken ct)=>{input.Id=Guid.NewGuid();input.TenantId=tenantId;input.CreatedAtUtc=input.UpdatedAtUtc=DateTime.UtcNow;templates.Apply(input);db.AutonomousAcquisitionAgents.Add(input);await db.SaveChangesAsync(ct);return Results.Created($"/api/autonomous-acquisition/tenants/{tenantId}/agents/{input.Id}",input);});g.MapGet("/tenants/{tenantId}/agents/{id}",async(Guid tenantId,Guid id,AppDbContext db,CancellationToken ct)=>{var a=await db.AutonomousAcquisitionAgents.SingleOrDefaultAsync(x=>x.TenantId==tenantId&&x.Id==id,ct);return a is null?Results.NotFound():Results.Ok(a);});g.MapPut("/tenants/{tenantId}/agents/{id}",async(Guid tenantId,Guid id,AutonomousAcquisitionAgent input,AppDbContext db,IAutonomousAcquisitionTemplateRegistry templates,CancellationToken ct)=>{var a=await db.AutonomousAcquisitionAgents.SingleOrDefaultAsync(x=>x.TenantId==tenantId&&x.Id==id,ct);if(a is null)return Results.NotFound();input.Id=id;input.TenantId=tenantId;input.CreatedAtUtc=a.CreatedAtUtc;input.UpdatedAtUtc=DateTime.UtcNow;templates.Apply(input);db.Entry(a).CurrentValues.SetValues(input);await db.SaveChangesAsync(ct);return Results.Ok(a);});g.MapPost("/tenants/{tenantId}/agents/{id}/activate",async(Guid tenantId,Guid id,AppDbContext db,CancellationToken ct)=>await SetStatus(tenantId,id,AutonomousAgentStatus.Active,db,ct));g.MapPost("/tenants/{tenantId}/agents/{id}/pause",async(Guid tenantId,Guid id,AppDbContext db,CancellationToken ct)=>await SetStatus(tenantId,id,AutonomousAgentStatus.Paused,db,ct));g.MapPost("/tenants/{tenantId}/agents/{id}/stop",async(Guid tenantId,Guid id,AppDbContext db,CancellationToken ct)=>await SetStatus(tenantId,id,AutonomousAgentStatus.Stopped,db,ct));g.MapPost("/tenants/{tenantId}/agents/{id}/run",async(Guid tenantId,Guid id,AppDbContext db,CancellationToken ct)=>{var a=await db.AutonomousAcquisitionAgents.SingleOrDefaultAsync(x=>x.TenantId==tenantId&&x.Id==id,ct);if(a is null)return Results.NotFound();if(a.Status is AutonomousAgentStatus.Stopped)return Results.BadRequest(new{error="Agent is stopped"});var run=new AutonomousAcquisitionAgentRun{TenantId=tenantId,AgentId=id,IsManual=true,Status=AutonomousAgentRunStatus.Queued};db.AutonomousAcquisitionAgentRuns.Add(run);await db.SaveChangesAsync(ct);return Results.Accepted($"/api/autonomous-acquisition/tenants/{tenantId}/agents/{id}/runs/{run.Id}",run);});g.MapGet("/tenants/{tenantId}/agents/{id}/runs",async(Guid tenantId,Guid id,AppDbContext db,CancellationToken ct)=>Results.Ok(await db.AutonomousAcquisitionAgentRuns.Where(x=>x.TenantId==tenantId&&x.AgentId==id).OrderByDescending(x=>x.ScheduledAtUtc).ToListAsync(ct)));g.MapGet("/tenants/{tenantId}/runs",async(Guid tenantId,AppDbContext db,CancellationToken ct)=>Results.Ok(await db.AutonomousAcquisitionAgentRuns.Where(x=>x.TenantId==tenantId).OrderByDescending(x=>x.ScheduledAtUtc).Take(100).ToListAsync(ct)));return e;}private static async Task<IResult> SetStatus(Guid tenantId,Guid id,AutonomousAgentStatus status,AppDbContext db,CancellationToken ct){var a=await db.AutonomousAcquisitionAgents.SingleOrDefaultAsync(x=>x.TenantId==tenantId&&x.Id==id,ct);if(a is null)return Results.NotFound();a.Status=status;a.UpdatedAtUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);return Results.Ok(a);}}
